<?php require 'config/database.php';require 'helpers/functions.php';login_required();header_html('Dashboard');
$stats=['Produk'=>(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn(),'Kategori'=>(int)$pdo->query('SELECT COUNT(*) FROM categories')->fetchColumn(),'Pemasok'=>(int)$pdo->query('SELECT COUNT(*) FROM suppliers')->fetchColumn(),'Total stok'=>(int)$pdo->query('SELECT COALESCE(SUM(stock),0) FROM products')->fetchColumn()];
echo '<div class="stats">';foreach($stats as $k=>$v)echo '<section><small>'.e($k).'</small><h2>'.number_format($v).'</h2></section>';echo '</div><section><h2>Stok menipis (≤ 5)</h2><table><tr><th>SKU</th><th>Produk</th><th>Stok</th></tr>';$rows=$pdo->query('SELECT sku,name,stock FROM products WHERE stock<=5 ORDER BY stock')->fetchAll();foreach($rows as $r)echo '<tr><td>'.e($r['sku']).'</td><td>'.e($r['name']).'</td><td>'.e($r['stock']).'</td></tr>';if(!$rows)echo '<tr><td colspan="3">Tidak ada stok menipis.</td></tr>';echo '</table></section>';footer_html();
